// Env bindings are generated by `wrangler types`; secret fields are declared separately.
import type { ModelEgress } from "./model-egress";
export type AppEnv = Omit<
  Cloudflare.Env,
  "DEV_MODE" | "ACCESS_AUD" | "MODEL_EGRESS"
> & {
  MODEL_EGRESS: DurableObjectNamespace<ModelEgress>;
  MASTER_KEY: string;
  DEV_MODE: string;
  ACCESS_AUD: string;
};
export type Variables = { deviceId: string; actor: "owner" | "device" };
